<template><div><h1>Settings</h1><AppInput v-model="days" placeholder="7,3,1"/><AppButton @click="save">Save</AppButton></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {useSettingsStore} from '../stores/settings';import AppInput from '../components/AppInput.vue';import AppButton from '../components/AppButton.vue';const store=useSettingsStore();const days=ref('7,3,1');onMounted(async()=>{await store.fetch();days.value=(store.reminder?.remindDaysBefore||[7,3,1]).join(',');});const save=()=>store.save({remindDaysBefore:days.value.split(',').map(Number)});</script>
